// Managed by the Game Master Triggers tab. Start/stop there, not from the hotbar.
if (!game.user.isGM) return;
if (!scope.runtime) { ui.notifications.info('Use the Game Master Triggers tab to start or stop this macro.'); return; }
const {trigger, Hooks, setInterval, enqueue, services} = scope.runtime;
const {ID, e, core, activeGM, createRequest} = services;
const {recoverCombatAmmo}=await import('/modules/morelord-game-master/scripts/ammo-recovery.mjs');
Hooks.on('deleteCombat',combat=>enqueue(()=>recoverCombatAmmo(combat)));
return true;
